// AD4-KEY-CHECK
// THE KEY IS NOT IN THIS FILE ANY MORE, AND THAT IS THE POINT.
//
// Every Supabase node in this workflow authenticates with an n8n SUPABASE
// CREDENTIAL rather than a key pasted into the Config node. That is one place
// to set it instead of twelve, it is encrypted at rest in n8n, and exporting
// this workflow can no longer leak it - the old shape had the service key
// sitting in plain text inside a JSON file that gets emailed around.
//
// SET IT UP ONCE, BEFORE IMPORTING ANYTHING:
//   n8n -> Credentials -> New -> Supabase API
//     Name         AD4 Supabase        <- this name exactly
//     Host         https://<your-project-ref>.supabase.co
//     Service Role the SERVICE ROLE key (Project Settings -> API keys)
//
// The name matters because every Supabase node in every AD4 workflow is
// already bound to a credential called AD4 Supabase. Create it first and
// n8n links all of them on import - nothing to pick node by node. Import
// first and the nodes come in unbound, and you pick the credential on each
// one by hand; it works, it is just ~57 dropdowns instead of zero.
//
// The credential sends `apikey` and `Authorization: Bearer` itself, which is
// exactly what these nodes used to set by hand.
//
// WHAT STILL CHECKS THE KEY. This node can no longer read it - a credential
// is not visible to an expression, by design. Two things downstream do:
//
//   the schedule gate, immediately below. sql/ad4_38 revokes should_run from
//   anon, so a credential holding the publishable key is refused HERE, two
//   nodes in, before a single row is fetched.
//
//   the write guard in the Summary node, which names any refusal the
//   database gives and refuses to report success on a run that wrote nothing.
//
// supabase_url stays in Config because an expression has to build the request
// URL and cannot read the credential's host. It is not a secret.
{
  const cfg = $('Config').first().json ?? {};
  const url = String(cfg.supabase_url ?? '').trim();
  if (!url) {
    throw new Error(
      'Config -> supabase_url is empty. Set it to exactly ' +
      'https://<your-project-ref>.supabase.co - no trailing slash and no /rest/v1, ' +
      'which every node below appends itself. The KEY does not go here: it belongs in ' +
      'the n8n Supabase credential (Credentials -> New -> Supabase API), which is ' +
      'where the nodes now read it from.');
  }
  if (!/^https:\/\//.test(url) || /\/rest\b/.test(url) || /\/$/.test(url)) {
    throw new Error(
      `Config -> supabase_url is "${url}", which is not the shape every node below ` +
      'expects: https://<your-project-ref>.supabase.co, no trailing slash, no /rest/v1. ' +
      'Nothing was fetched and nothing was written.');
  }
}

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE. 42501 here means the key
// cannot even call should_run, and a key that cannot do that cannot write
// either - so stop, rather than failing open into a run that writes nothing.
//
// THIS NODE CANNOT CHECK THE KEY ITSELF ANY MORE - it is in the credential,
// which an expression cannot read. So a refusal here is one of two things and
// both stop the run: the credential holds the anon/publishable key rather than
// the service role key, or service_role has not been granted what it needs.
// Either way every write below would be refused the same way, so there is
// nothing to gain by going on. ad4_38's output tells you which it was.
//
// ad4_38 revokes should_run from anon for this reason: it was granted so the
// Workflows page could preview a cadence, that page reads v_execution_budget
// instead, and the grant only let a bad key through the gate.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). Every write below ` +
    `would be refused the same way, so nothing was fetched and nothing was written. Two ` +
    `things cause this and the workflow cannot tell them apart, because the key now lives ` +
    `in the n8n credential where an expression cannot read it. (1) THE KEY: open n8n -> ` +
    `Credentials -> the Supabase account these nodes use and check Service Role Secret ` +
    `holds the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or a ` +
    `key beginning sb_secret_) - an anon key gets exactly this error, because anon is ` +
    `granted SELECT and nothing else. NEVER put the service key anywhere starting ` +
    `NEXT_PUBLIC_. (2) THE DATABASE: service_role has not been granted what it needs. Run ` +
    `sql/ad4_38_grants.sql in the Supabase SQL editor - it grants the write path back and ` +
    `then prints one row per ingest table saying whether the service key can write it, ` +
    `which also tells you which of the two it was.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;

// ONE request for every city. Open-Meteo takes comma-separated coordinate
// lists and answers with one object per location, in the order asked - so 37
// cities cost one HTTP call rather than 37, and there is no rate limit to
// pace against.
//
// It is also GLOBAL, which is the entire reason this workflow exists.
// api.weather.gov covers the US and its territories; Warsaw, Ankara, Moscow
// and Jinan get a 404 from it and were therefore left with no live reading
// and no forward forecast from any job at all.
const cfg = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json).flat();
const cap = Number(cfg.max_cities_per_run || 0) || 0;
const horizon = Number(cfg.max_horizon_days || 7);

const use = [];
// SCOPE. run_scope() decides which cities this run covers and should_run()
// carries the answer, so this costs no extra node and no extra request. A
// workflow that ignores the field behaves exactly as it always did; absent,
// "all", or a selection matching nothing all mean every active city, because
// a scope that silently reduces a run to zero is indistinguishable from a
// broken job.
const _scope = (($('Check schedule').first().json ?? {}).scope) ?? {};
const _only = Array.isArray(_scope.cities) && _scope.cities.length
  ? new Set(_scope.cities) : null;

for (const c of cities) {
  if (!c || !c.city_key) continue;
  if (_only && !_only.has(c.city_key)) continue;
  if (c.latitude == null || c.longitude == null) continue;
  if (c.status && c.status !== 'active') continue;
  use.push({
    city_key: c.city_key,
    timezone: c.timezone || null,
    latitude: Number(c.latitude),
    longitude: Number(c.longitude),
  });
  if (cap && use.length >= cap) break;
}
if (use.length === 0) {
  throw new Error(
    'No active cities with coordinates. Open-Meteo is addressed by lat/lon - ' +
    'check cities.latitude / longitude are populated and status is active.');
}

// UNITS ARE REQUESTED TO MATCH THE COLUMNS THEY LAND IN, not to taste.
// The observation archive came from IEM METAR, so its wind_speed column is
// KNOTS and its precip column is INCHES. Asking Open-Meteo for km/h and mm
// and writing them through unconverted puts
// 37 in a knots column for a 20kt wind - wrong, and not wrong-LOOKING, which
// is the kind of error nobody finds. cloud_cover is the one Open-Meteo cannot
// serve in the stored unit: it answers percent and the column is oktas, so
// Build rows converts it.
const HOURLY = ['temperature_2m', 'relative_humidity_2m', 'dew_point_2m',
                'apparent_temperature', 'precipitation', 'precipitation_probability',
                'cloud_cover', 'wind_speed_10m', 'surface_pressure'];
const CURRENT = ['temperature_2m', 'relative_humidity_2m', 'dew_point_2m',
                 'apparent_temperature', 'precipitation', 'cloud_cover',
                 'wind_speed_10m', 'wind_direction_10m', 'surface_pressure',
                 'is_day'];

// The query string is built by hand. The Code node sandbox does not define
// the browser's URL query-builder class, and a workflow that dies with
// ReferenceError on its first node is worse than a slightly longer join.
const params = {
  latitude: use.map(c => c.latitude.toFixed(4)).join(','),
  longitude: use.map(c => c.longitude.toFixed(4)).join(','),
  hourly: HOURLY.join(','),
  current: CURRENT.join(','),
  // lead 0 through `horizon`, so one more day than the horizon itself
  forecast_days: String(Math.min(16, Math.max(2, horizon + 1))),
  // Each location gets ITS OWN local time, which is the only clock a daily
  // maximum means anything in.
  timezone: 'auto',
  temperature_unit: 'celsius',
  wind_speed_unit: 'kn',
  precipitation_unit: 'inch',
};
const q = Object.keys(params)
  .map(k => `${k}=${encodeURIComponent(params[k])}`)
  .join('&');

return [{ json: { url: `https://api.open-meteo.com/v1/forecast?${q}`,
                  cities: use, n: use.length } }];

// One Open-Meteo response per city, paired back by position, into three
// shapes: a live reading, a daily maximum per forecast day, and the drivers
// behind that maximum.
const cfg = $('Config').first().json;
const model = cfg.model_label || 'open_meteo_forecast';
const horizon = Number(cfg.max_horizon_days || 7);
const morningHour = Number(cfg.morning_hour || 8);
const [winFrom, winTo] = String(cfg.peak_window || '12-18').split('-').map(Number);

const req = $('Build requests').first().json;
const cities = req.cities || [];

// n8n splits a JSON array body into one item per element, so a multi-location
// answer arrives as N items. A single-location answer is a bare object and
// arrives as one. Handle both rather than assuming the shape that happens to
// be true for 37 cities and false for the one-city test.
let res = $('Fetch open-meteo').all().map(i => i.json);
if (res.length === 1 && Array.isArray(res[0])) res = res[0];

if (res.length !== cities.length) {
  throw new Error(
    `Open-Meteo returned ${res.length} location(s) for ${cities.length} cities. ` +
    `Rows are paired by position, so a mismatch would file one city's weather ` +
    `under another. Nothing was written.`);
}

// Open-Meteo answers cloud cover in PERCENT. Both the forecast-feature table
// and the observation archive store OKTAS - eighths - because that is what
// METAR reports and what the model was fitted on. 100% is 8 oktas, not 100.
function oktas(pct) {
  if (pct === null || pct === undefined) return null;
  const v = Number(pct);
  if (!Number.isFinite(v)) return null;
  return Math.max(0, Math.min(8, Math.round(v / 12.5)));
}
function num(v) {
  if (v === null || v === undefined) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function r2(v) { return v === null ? null : Number(v.toFixed(2)); }
function compass(deg) {
  if (deg === null || deg === undefined) return null;
  const pts = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
  return pts[Math.round(Number(deg) / 22.5) % 16];
}

const now = new Date().toISOString();
const forecasts = [], features = [], live = [];
let ok = 0, failed = 0, partial = 0;
let firstFailure = null;

for (let i = 0; i < cities.length; i++) {
  const city = cities[i];
  const r = res[i] || {};

  if (r.error || r.reason) {
    failed++;
    if (!firstFailure) firstFailure = { city: city.city_key, reason: String(r.reason || r.error).slice(0, 300) };
    continue;
  }

  const h = r.hourly || {};
  const times = Array.isArray(h.time) ? h.time : [];
  if (!times.length) {
    failed++;
    if (!firstFailure) firstFailure = {
      city: city.city_key, reason: 'no hourly series in the response',
      keys: Object.keys(r).slice(0, 12), body: JSON.stringify(r).slice(0, 300) };
    continue;
  }

  // ---- the live reading -------------------------------------------------
  // live_weather only, and deliberately. Open-Meteo's `current` is model
  // output interpolated to a coordinate, not an instrument reading at the
  // ICAO the market settles on - so it must never reach the raw observation
  // archive, which is the settlement evidence and what the model is fitted
  // on. Training a model on its own kind of guess is how a desk convinces
  // itself it is right.
  const cur = r.current || {};
  const rawTime = String(cur.time || '');
  const offset = Number(r.utc_offset_seconds);
  const currentMs = /(?:Z|[+-]\d{2}:\d{2})$/.test(rawTime)
    ? Date.parse(rawTime)
    : (rawTime && r.utc_offset_seconds !== undefined && Number.isFinite(offset)
      ? Date.parse(rawTime + 'Z') - offset * 1000 : NaN);
  const currentValid = Number.isFinite(currentMs) && currentMs <= Date.parse(now);

  if (num(cur.temperature_2m) !== null && currentValid) {
    const tc = num(cur.temperature_2m);
    live.push({
      city_key: city.city_key,
      updated_at: now,
      observed_at: new Date(currentMs).toISOString(),
      temp_c: r2(tc),
      temp_f: r2(tc * 9 / 5 + 32),
      feels_like_c: r2(num(cur.apparent_temperature)),
      humidity: num(cur.relative_humidity_2m),
      wind_speed_kt: r2(num(cur.wind_speed_10m)),
      wind_dir_deg: num(cur.wind_direction_10m),
      wind_dir_compass: compass(num(cur.wind_direction_10m)),
      pressure_hpa: r2(num(cur.surface_pressure)),
      precip_1h: num(cur.precipitation),
      sky_condition: oktas(cur.cloud_cover) === null ? null
                   : (oktas(cur.cloud_cover) <= 1 ? 'CLEAR'
                   : oktas(cur.cloud_cover) <= 4 ? 'PARTLY'
                   : oktas(cur.cloud_cover) <= 7 ? 'CLOUDY' : 'OVERCAST'),
      local_date: rawTime.slice(0, 10),
      source: 'open-meteo',
      source_kind: 'model',
      obs_source: 'open-meteo',
      running_max_c: null, running_max_at: null, running_min_c: null,
      temp_change_1h: null, temp_change_3h: null, trend: null,
      minutes_to_peak: null, peak_window_state: null, day_decided: false,
      visibility_m: null, max_temp_24h_c: null,
    });
  }

  // ---- the forecast, by the city's own local day -------------------------
  // timezone=auto means these timestamps are already local, so slicing the
  // date off gives the calendar day a daily maximum belongs to, with no
  // timezone table on this side.
  const byDay = new Map();
  for (let k = 0; k < times.length; k++) {
    const day = String(times[k]).slice(0, 10);
    const hour = Number(String(times[k]).slice(11, 13));
    const t = num(h.temperature_2m ? h.temperature_2m[k] : null);
    if (t === null) continue;
    if (!byDay.has(day)) byDay.set(day, {
      hours: new Set(), max: -Infinity, min: Infinity, at: null, n: 0,
      cloud: [], wind: [], precip: 0, pop: [], apparentMax: -Infinity,
      morning: null, morningGap: Infinity,
    });
    const d = byDay.get(day);
    d.hours.add(hour); d.n++;
    if (t > d.max) { d.max = t; d.at = times[k]; }
    if (t < d.min) d.min = t;

    const ap = num(h.apparent_temperature ? h.apparent_temperature[k] : null);
    if (ap !== null && ap > d.apparentMax) d.apparentMax = ap;

    // daytime drivers only: what the sun had to work through
    if (hour >= 9 && hour <= 17) {
      const c = oktas(h.cloud_cover ? h.cloud_cover[k] : null);
      if (c !== null) d.cloud.push(c);
      const w = num(h.wind_speed_10m ? h.wind_speed_10m[k] : null);
      if (w !== null) d.wind.push(w);
    }
    const pr = num(h.precipitation ? h.precipitation[k] : null);
    if (pr !== null) d.precip += pr;
    const pp = num(h.precipitation_probability ? h.precipitation_probability[k] : null);
    if (pp !== null) d.pop.push(pp);

    // the reading nearest the morning hour, for dewpoint depression - the
    // single-instant quantity, not two series averaged and subtracted
    const gap = Math.abs(hour - morningHour);
    if (gap < d.morningGap) {
      d.morningGap = gap;
      d.morning = {
        temp: t,
        dew: num(h.dew_point_2m ? h.dew_point_2m[k] : null),
        rh: num(h.relative_humidity_2m ? h.relative_humidity_2m[k] : null),
      };
    }
  }

  const days = [...byDay.keys()].sort();
  if (!days.length) { failed++; continue; }
  const today = days[0];
  let wrote = 0;

  for (const day of days) {
    const d = byDay.get(day);
    // A day whose series misses the peak window has an understated maximum,
    // and a too-low max invents disagreement with the other model out of
    // nothing. Skip it rather than write it wrong.
    let covered = true;
    for (let hr = winFrom; hr <= winTo; hr++) if (!d.hours.has(hr)) { covered = false; break; }
    if (!covered) { partial++; continue; }

    const lead = Math.round((Date.parse(day + 'T00:00:00Z') - Date.parse(today + 'T00:00:00Z')) / 86400000);
    if (lead < 0 || lead > horizon) continue;

    const mean = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;

    forecasts.push({
      city_key: city.city_key, model, run_at: now, for_date: day,
      lead_days: lead, forecast_max_c: r2(d.max), source: 'open-meteo',
      variables: {
        min_c: r2(d.min), max_at_local: d.at, n_hours: d.n,
        peak_window: `${winFrom}-${winTo}`, issued_at: now,
      },
    });

    // The same column NAMES as the observed features, so a model fitted on
    // days that already happened reads a forecast day with no translation.
    features.push({
      city_key: city.city_key, for_date: day, run_at: now,
      source: 'open-meteo', lead_days: lead,
      forecast_max_c: r2(d.max), forecast_min_c: r2(d.min),
      apparent_max_c: d.apparentMax === -Infinity ? null : r2(d.apparentMax),
      morning_temp_c: d.morning ? r2(d.morning.temp) : null,
      morning_dewpoint_c: d.morning ? r2(d.morning.dew) : null,
      dewpoint_depression_c: (d.morning && d.morning.dew !== null)
        ? r2(d.morning.temp - d.morning.dew) : null,
      morning_humidity: d.morning ? d.morning.rh : null,
      cloud_mean: r2(mean(d.cloud)), cloud_max: d.cloud.length ? Math.max(...d.cloud) : null,
      wind_mean: r2(mean(d.wind)), wind_max: d.wind.length ? r2(Math.max(...d.wind)) : null,
      precip_total: Number(d.precip.toFixed(4)),
      precip_probability: d.pop.length ? Math.max(...d.pop) : null,
      n_hours: d.n,
    });
    wrote++;
  }
  if (wrote) ok++; else failed++;
}

return [{ json: {
  forecasts, features, live,
  n_forecasts: forecasts.length, n_features: features.length, n_live: live.length,
  cities_ok: ok, cities_failed: failed, partial_days: partial,
  requested: cities.length, first_failure: firstFailure,
} }];

const p = $('Build rows').first().json;
if (p.n_forecasts === 0 && p.n_live === 0) {
  const f = p.first_failure;
  // The cause first: n8n's banner shows one line and one line is what gets
  // pasted into a report.
  let why = 'Open-Meteo returned nothing usable and no failing location was captured.';
  if (f && f.reason) {
    why = /timezone|latitude|longitude/i.test(f.reason)
      ? `Open-Meteo rejected the request: ${f.reason}. Check cities.latitude / longitude are real coordinates.`
      : `Open-Meteo returned no hourly series: ${f.reason}`;
    if (f.keys) why += ` Keys: ${f.keys.join(', ')}.`;
  }
  throw new Error(
    why + ` [${p.cities_failed}/${p.requested} failed, ${p.partial_days} day(s) ` +
    `skipped for not covering the peak window, nothing written]` +
    (f ? `\n\nFirst failing city: ${f.city}` : ''));
}
return [{ json: p }];

const AD4_WRITE_NODES = ["Write live_weather", "Write forecasts", "Write forecast features"];
// AD4-WRITE-GUARD
// DID THE DATABASE ACTUALLY TAKE IT?
//
// Every write node in this workflow carries onError=continueRegularOutput so
// that one bad row cannot kill a run. The cost of that is a REFUSED write
// walks straight past it and arrives here looking healthy - which is how a
// workflow reports "ok, 0 rows" for days while the data quietly stops moving.
//
// With neverError on, a refusal arrives as the PostgREST error body instead of
// an exception, so it can be read and named. That is what this does.
function ad4WriteError(node) {
  // WHAT ACTUALLY WENT WRONG, NOT THE FIRST THING THAT LOOKED LIKE AN ERROR.
  //
  // This used to return the first item carrying a `code` or `message` and stop.
  // A Supabase gateway timeout arrives as {"data":"upstream request timeout"} -
  // no code, no message - so it was skipped ENTIRELY, and on a run where 90 of
  // 102 writes timed out the guard reported the single PGRST102 it found
  // instead. The message named a key mismatch; the cause was an overloaded
  // database. That cost an evening.
  //
  // So: classify every item, count the kinds, and report the one that
  // dominates, with the counts, so the next person reads the truth first.
  let items;
  try { items = $(node).all(); } catch (e) { return null; }
  const kinds = {};
  let first = null, n = 0;
  for (const it of items || []) {
    const b = it && it.json;
    if (!b || typeof b !== 'object') continue;
    n++;
    let e = null;
    if (typeof b.data === 'string' && /timeout|timed out|502|503|504/i.test(b.data)) {
      e = { node, code: 'TIMEOUT', message: b.data.slice(0, 300) };
    } else if (b.error && !b.code) {
      e = { node, code: null, message: String(b.error).slice(0, 300) };
    } else if (b.code || b.message) {
      e = { node, code: b.code ?? null, message: b.message ?? '',
            details: b.details ?? null, hint: b.hint ?? null };
    }
    if (!e) continue;
    const key = String(e.code ?? e.message).slice(0, 60);
    kinds[key] = (kinds[key] || 0) + 1;
    if (!first || kinds[key] > kinds[String(first.code ?? first.message).slice(0, 60)]) first = e;
  }
  if (!first) return null;
  const key = String(first.code ?? first.message).slice(0, 60);
  first.count = kinds[key];
  first.of = n;
  first.kinds = kinds;
  return first;
}

for (const node of AD4_WRITE_NODES) {
  const e = ad4WriteError(node);
  if (!e) continue;
  // 42501 is the one worth naming, because the cause is never in the code.
  if (String(e.code) === 'TIMEOUT') {
    throw new Error(
      `Supabase did not answer ${e.count} of ${e.of} write(s) at "${e.node}": ${e.message}. ` +
      `That is the DATABASE being too busy to reply, not a bad row - retrying the same run ` +
      `harder will not help. Check whether several workflows are running at once, and look ` +
      `at the Supabase project's load. Whatever did not time out was written; the rest was not.`);
  }
  if (String(e.code) === '42501' || /permission denied/i.test(e.message)) {
    throw new Error(
      `Supabase REFUSED the write at "${e.node}": ${e.message} (${e.code}). The key was ` +
      `already checked at "Run now?" and claims to be the service key, so this is the ` +
      `DATABASE side: service_role has no INSERT on that table. Run sql/ad4_38_grants.sql ` +
      `in the Supabase SQL editor - it grants the write path back, then prints one row per ` +
      `ingest table saying whether the service key can write it. Nothing was written.`);
  }
  if (String(e.code) === '42P01') {
    throw new Error(
      `Supabase has no such table for "${e.node}": ${e.message}. The sql/ files that create ` +
      `it have not been run - sql/ad4_98_ui_health.sql names which file owns which table. ` +
      `Nothing was written.`);
  }
  throw new Error(
    `Supabase refused the write at "${e.node}": ${e.message}` +
    (e.code ? ` (${e.code})` : '') + (e.details ? ` - ${e.details}` : '') +
    (e.hint ? ` Hint: ${e.hint}` : '') + ' Nothing was written.');
}

const p = $('Build rows').first().json;
const summary =
  `AD4 P1.5: ${p.n_forecasts} forecast day(s) and ${p.n_live} live reading(s) ` +
  `from ${p.requested} cities` +
  (p.cities_failed ? `, ${p.cities_failed} failed` : '') +
  (p.partial_days ? `, ${p.partial_days} day(s) skipped for peak-window coverage` : '') + '.';
const status = p.n_forecasts > 0 ? 'ok' : 'attention';
return [{ json: {
  summary, status, rows: p.n_forecasts + p.n_live,
  log: { p_job: 'P1.5_open_meteo', p_status: status,
         p_rows: p.n_forecasts + p.n_live,
         p_detail: { forecasts: p.n_forecasts, features: p.n_features,
                     live: p.n_live, cities_ok: p.cities_ok,
                     cities_failed: p.cities_failed, partial_days: p.partial_days,
                     requested: p.requested, summary,
                     trigger: $execution.mode, execution_id: $execution.id } },
} }];
